12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
43	    }
44	
45	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
46	    @PostMapping("/seed")
47	    @SuppressWarnings("unchecked")
48	    public void seed(@RequestBody Map<String, Object> fixture) {
49	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
50	        if (clients != null) {
51	            for (Map<String, Object> client : clients) {
52	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
53	                jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
54	                        ((Number) client.get("id")).longValue(), client.get("name"),
55	                        client.get("email"));
56	            }
57	        }
58	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
59	        if (projects != null) {
60	            for (Map<String, Object> project : projects) {
61	                jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
62	                        ((Number) project.get("id")).longValue(), project.get("name"),
63	                        ((Number) project.get("clientId")).longValue());
64	            }
65	        }
66	        List<Map<String, Object>> contacts = (List<Map<String, Object>>) fixture.get("contacts");
67	        if (contacts != null) {
68	            for (Map<String, Object> contact : contacts) {
69	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role)"
70	                        + " VALUES (?, ?, ?, ?, ?)",
71	                        ((Number) contact.get("id")).longValue(),
72	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
73	                        contact.get("email"), contact.get("role"));
74	            }
75	        }
